function onOutside(event) {
  if (!menu.contains(event.target)) closeMenu();
}

function openMenu() {
  menu.hidden = false;
  document.addEventListener("click", onOutside, true);
}

function closeMenu() {
  menu.hidden = true;
  document.removeEventListener("click", onOutside);
}

